/**
 * The measurement, written down.
 *
 * Every cell here was produced by `score.ts` over `corpus.json` — seven gate
 * designs, seven faults, each cell a count of how many of the sixteen recorded
 * runs that design fired on — and `runs.test.ts` produces them all again on
 * every `pnpm test` and fails if any cell has moved. Nothing in this file is
 * computed from the thing it describes, which is the only reason it is worth
 * reading: a table generated by the code it scores agrees with it by
 * construction.
 *
 * `README.md` renders these cells and `readme.test.ts` checks that it renders
 * *these* cells, so the document cannot drift from the table and the table
 * cannot drift from the corpus.
 *
 * ---------------------------------------------------------------------------
 * Reading a cell
 * ---------------------------------------------------------------------------
 * A cell is `fired/16`. The column header says what the right answer is:
 *
 *   - under `none` and `tiny-doubled`, both `quiet` faults, the right answer
 *     is **0** — anything else is a build failed for nothing.
 *   - under the five `fire` faults the right answer is **16** — the regression
 *     is there in every run, so a design that notices it in some of them has
 *     noticed the scheduler instead.
 *
 * Which makes the interesting cells the ones that are neither: `file-percent`
 * firing on 3 of 16 unchanged runs, and `file-absolute` firing on 1 of 16
 * identical regressions. Both are thresholds sitting inside the noise.
 */

import { FAULT_IDS, type FaultId } from './faults.ts'
import { GATE_IDS, type GateId } from './gates.ts'

/** How many runs the corpus holds, and so the denominator of every cell. */
export const RUNS = 16

function cell(encoded: number): number {
  if (!Number.isInteger(encoded) || encoded < 0 || encoded > RUNS) {
    throw new Error(`not a count out of ${String(RUNS)}: ${String(encoded)}`)
  }

  return encoded
}

/** One gate's row, in the column order of `FAULT_IDS`. */
function row(...counts: readonly number[]): Readonly<Record<FaultId, number>> {
  if (counts.length !== FAULT_IDS.length) {
    throw new Error(`a row needs ${String(FAULT_IDS.length)} cells, got ${String(counts.length)}`)
  }

  return Object.fromEntries(
    FAULT_IDS.map((faultId, index) => [faultId, cell(counts[index] ?? -1)]),
  ) as Readonly<Record<FaultId, number>>
}

/**
 * The table.
 *
 * Columns, in order: none, tiny-doubled, small-tripled, medium-doubled,
 * large-tenth, creep, new-file.
 */
export const TABLE: Readonly<Record<GateId, Readonly<Record<FaultId, number>>>> = {
  //                            none  tiny  small  medium  large  creep  new
  'none':                 row(     0,    0,     0,     0,     0,     0,    0),
  'file-percent':         row(     3,   16,    16,    16,     3,     3,    3),
  'file-percent-floored': row(     0,    0,     0,    16,     0,     0,    0),
  'file-absolute':        row(     0,    0,     0,    16,     1,     0,    0),
  'file-both':            row(     0,    0,     0,    16,     0,     0,    0),
  'total-percent':        row(     0,    0,    16,    16,    16,    16,   16),
  'recommended':          row(     0,    0,    16,    16,    16,    16,   16),
}

/** How many faults each design answers correctly in every run, out of seven. */
export const TALLIES: Readonly<Record<GateId, number>> = {
  'none': 2,
  'file-percent': 2,
  'file-percent-floored': 3,
  'file-absolute': 3,
  'file-both': 3,
  'total-percent': 7,
  'recommended': 7,
}

export const TOTAL_CELLS = GATE_IDS.length * FAULT_IDS.length

/** One cell, by row and column. */
export function scored(gateId: GateId, faultId: FaultId): number {
  const gateRow = TABLE[gateId]
  const value = gateRow[faultId]

  if (value === undefined) throw new Error(`no cell for ${gateId} × ${faultId}`)

  return value
}
